1	// Vercel Cron sends `authorization: Bearer ${CRON_SECRET}`. These routes spend
2	// real money — transcription, gateway inference — across every tenant, so a
3	// missing secret must close the route rather than open it. The previous
4	// `if (secret && ...)` form meant an unset variable left them anonymously
5	// reachable, which is the opposite of what an unconfigured deployment wants.
6	export const requireCronSecret = (request: Request): Response | null => {
7	  const secret = process.env.CRON_SECRET;
8	  if (!secret) {
9	    return new Response("CRON_SECRET is not configured", { status: 503 });
10	  }
11	  if (request.headers.get("authorization") !== `Bearer ${secret}`) {
12	    return new Response("Unauthorized", { status: 401 });
13	  }
14	  return null;
15	};
