9	// Crash safety without transactions, shared by every pipeline writer: _ids are
10	// derived deterministically from stable seeds, so a re-run after a mid-write
11	// crash re-attempts the same inserts and duplicate keys mean "already done".
12	
13	export const deterministicId = (seed: string): ObjectId =>
14	  new ObjectId(createHash("md5").update(seed).digest("hex").slice(0, 24));
15	
16	export const insertIgnoringDuplicate = async <T extends Document>(
17	  collection: Collection<T>,
18	  doc: T
19	): Promise<void> => {
20	  try {
21	    await collection.insertOne(doc as never);
22	  } catch (error) {
23	    const alreadyDone =
24	      error instanceof MongoServerError && error.code === 11_000;
25	    if (!alreadyDone) {
26	      throw error;
27	    }
28	  }
29	};
